:root {
  --bg: #1a1c2c;
  --panel: #2d2b45;
  --primary: #e85f5c;
  --accent: #f4a261;
  --text: #f7e3af;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem 1rem;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  color: var(--text);
  background-color: var(--bg);
  background-image:
    linear-gradient(rgba(247, 227, 175, 0.08) 1px, transparent 1px),
    linear-gradient(90deg, rgba(247, 227, 175, 0.08) 1px, transparent 1px);
  background-size: 24px 24px;
}

.game-board {
  width: min(92%, 420px);
  padding: 1.75rem;
  background: var(--panel);
  border: 4px solid #1a1c2c;
  box-shadow: 8px 8px 0 var(--primary);
  color: var(--text);
  border-radius: 0;
}

h1 {
  margin: 0 0 1.25rem;
  font-size: clamp(1.5rem, 6vw, 2rem);
  line-height: 1.1;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  text-shadow: 3px 3px 0 #1a1c2c;
}

label,
legend {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: bold;
  color: var(--accent);
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

input[type="number"] {
  width: 100%;
  padding: 0.75rem;
  margin-bottom: 1rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid #1a1c2c;
  border-radius: 0;
  box-shadow: inset 3px 3px 0 rgba(0, 0, 0, 0.25);
  font: inherit;
  outline: none;
}

input[type="number"]:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(244, 162, 97, 0.5), inset 3px 3px 0 rgba(0, 0, 0, 0.25);
}

.input-wrap {
  position: relative;
}

.input-wrap .currency {
  position: absolute;
  left: 0.75rem;
  top: 1.65rem;
  pointer-events: none;
  color: var(--text);
  font-weight: bold;
}

.input-wrap input {
  padding-left: 2rem;
}

.tip-group {
  margin-bottom: 1rem;
}

.tip-buttons {
  display: flex;
  gap: 0.75rem;
}

.tip-button {
  flex: 1;
  padding: 0.65rem 0.25rem;
  background: var(--bg);
  color: var(--text);
  border: 3px solid #1a1c2c;
  border-radius: 0;
  box-shadow: 0 4px 0 var(--primary);
  font: inherit;
  font-weight: bold;
  cursor: pointer;
  transition: transform 0.06s ease, box-shadow 0.06s ease, background-color 0.06s ease;
}

.tip-button:hover {
  background: var(--primary);
  color: var(--bg);
  transform: translateY(-2px);
  box-shadow: 0 6px 0 #1a1c2c;
}

.tip-button.is-selected {
  background: var(--primary);
  color: var(--bg);
  box-shadow: 0 4px 0 #1a1c2c;
}

.tip-button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.tip-button:active {
  transform: translateY(4px);
  box-shadow: 0 0 0 var(--primary);
}

.results {
  margin-top: 1.5rem;
  padding-top: 1rem;
  border-top: 4px dashed var(--accent);
  display: grid;
  gap: 0.75rem;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
  background: var(--bg);
  border: 3px solid #1a1c2c;
  padding: 0.75rem;
  box-shadow: inset 3px 3px 0 rgba(0, 0, 0, 0.25);
}

.result-row span {
  font-weight: bold;
  color: var(--accent);
}

output {
  font-size: 1.35rem;
  font-weight: bold;
  color: var(--primary);
  font-variant-numeric: tabular-nums;
}

@media (max-width: 380px) {
  .game-board {
    padding: 1.25rem;
    box-shadow: 5px 5px 0 var(--primary);
  }

  .tip-buttons {
    gap: 0.45rem;
  }

  .tip-button {
    font-size: 0.95rem;
  }

  output {
    font-size: 1.15rem;
  }
}

(function () {
  const billInput = document.getElementById('bill-amount');
  const peopleInput = document.getElementById('people-count');
  const tipButtons = Array.from(document.querySelectorAll('.tip-button'));
  const tipAmountOutput = document.getElementById('tip-amount');
  const totalPerPersonOutput = document.getElementById('total-per-person');

  let selectedTip = 15;

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function calculate() {
    const bill = parseFloat(billInput.value);
    const people = parseInt(peopleInput.value, 10);

    if (isNaN(bill) || bill <= 0 || isNaN(people) || people <= 0) {
      tipAmountOutput.textContent = '$0.00';
      totalPerPersonOutput.textContent = '$0.00';
      return;
    }

    const tip = bill * selectedTip / 100;
    const total = bill + tip;
    const perPerson = total / people;

    tipAmountOutput.textContent = formatCurrency(tip);
    totalPerPersonOutput.textContent = formatCurrency(perPerson);
  }

  function selectTip(tip) {
    selectedTip = tip;
    tipButtons.forEach(function (button) {
      const isSelected = Number(button.dataset.tip) === tip;
      button.classList.toggle('is-selected', isSelected);
      button.setAttribute('aria-pressed', isSelected ? 'true' : 'false');
    });
    calculate();
  }

  tipButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      selectTip(Number(button.dataset.tip));
    });
  });

  billInput.addEventListener('input', calculate);
  peopleInput.addEventListener('input', calculate);

  selectTip(15);
})();
